ALTER TABLE public.course_enrollments ADD COLUMN IF NOT EXISTS resource_payment_evidence jsonb;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS resource_download_allowed boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.resource_evidence_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_user IN ('authenticated','anon') AND NEW.resource_payment_evidence IS DISTINCT FROM OLD.resource_payment_evidence THEN RAISE EXCEPTION 'Verified payment evidence is server managed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER resource_evidence_guard BEFORE UPDATE ON public.course_enrollments FOR EACH ROW EXECUTE FUNCTION public.resource_evidence_guard();
CREATE OR REPLACE FUNCTION public.invalidate_family_recipient() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.saved_patients; BEGIN IF NEW.email IS DISTINCT FROM OLD.email OR NEW.active IS DISTINCT FROM OLD.active THEN FOR p IN SELECT * FROM public.saved_patients WHERE workspace_id=NEW.workspace_id AND family_update_preparation->>'contactId'=NEW.id::text FOR UPDATE LOOP UPDATE public.saved_patients SET family_update_preparation=family_update_preparation||jsonb_build_object('emailConfirmed',false,'deliveryEnabled',false,'state','recipient_changed_review_required','invalidatedAt',now()) WHERE id=p.id; INSERT INTO public.account_relationship_events(workspace_id,record_id,action,actor_id,details) VALUES(p.workspace_id,p.id,'family_recipient_invalidated',auth.uid(),jsonb_build_object('contactId',NEW.id,'deliveryEnabled',false)); END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER invalidate_family_recipient AFTER UPDATE OF email,active ON public.provider_contacts FOR EACH ROW EXECUTE FUNCTION public.invalidate_family_recipient();
ALTER TABLE public.vehicles ADD COLUMN IF NOT EXISTS operation_type text NOT NULL DEFAULT 'human_driven' CHECK(operation_type IN ('human_driven','future_autonomous'));
CREATE OR REPLACE FUNCTION public.prevent_autonomous_assignment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.vehicle_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.vehicles WHERE id=NEW.vehicle_id AND operation_type='future_autonomous') THEN RAISE EXCEPTION 'Future autonomous vehicles are not available for live assignment'; END IF; RETURN NEW; END $$;
CREATE TRIGGER prevent_autonomous_assignment BEFORE INSERT OR UPDATE OF vehicle_id ON public.trips FOR EACH ROW EXECUTE FUNCTION public.prevent_autonomous_assignment();
COMMENT ON COLUMN public.course_enrollments.resource_payment_evidence IS 'Server-attested completed purchase, exact line item and reversal evidence; NULL legacy records require verification, never inferred from enrollment.';